#' Dummy variables
#'
#' 
#' @param data .
#' @param vars Variabili categoriali (nominali, ordinali o di testo) da cui
#'   creare le dummy: una variabile 0/1 per ciascuna modalità, oppure per
#'   ciascuna opzione se \code{multi} è TRUE.
#' @param multi Se TRUE ogni cella può contenere più opzioni separate da
#'   \code{sep}, come nelle domande a risposta multipla di Moduli Google, e si
#'   crea una dummy per ciascuna opzione.
#' @param sep Il carattere che separa le opzioni nelle risposte multiple.
#' @param minAltro Con la risposta multipla, le opzioni scelte da meno di
#'   \code{minAltro} rispondenti, come le risposte libere della voce Altro,
#'   finiscono in un'unica dummy «altro». Con 1 non si riunisce nessuna opzione.
#' @param tuto Se TRUE mostra il pannello con la descrizione dell'analisi.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dummies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dummiesOV} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$dummies$asDF}
#'
#' \code{as.data.frame(results$dummies)}
#'
#' @export
dummies <- function(
    data,
    vars,
    multi = FALSE,
    sep = ",",
    minAltro = 2,
    tuto = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("dummies requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))

    for (v in vars) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- dummiesOptions$new(
        vars = vars,
        multi = multi,
        sep = sep,
        minAltro = minAltro,
        tuto = tuto)

    analysis <- dummiesClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

